const t = $('Sub').first().json;
const emb = $input.item.json.data[0].embedding;
const esc = (s) => String(s).replace(/'/g, "''");
let sourcesArr = "'{sessions,jobs,opportunities,forum,plain,gong,slack}'::text[]";
if (t.sources) {
  const parts = String(t.sources).split(',').map(s => s.trim()).filter(Boolean);
  if (parts.length) sourcesArr = "'{" + parts.join(',') + "}'::text[]";
}
const within = t.within ? "'" + esc(t.within) + "'::ltree" : 'null';
const approved = (t.approved === undefined || t.approved === null || t.approved === '') ? 'null' : (String(t.approved) === 'true' ? 'true' : 'false');
const projectId = t.project_id ? "'" + esc(t.project_id) + "'::uuid" : 'null';
const dateFrom = t.date_from ? "'" + esc(t.date_from) + "'::date" : 'null';
const dateTo = t.date_to ? "'" + esc(t.date_to) + "'::date" : 'null';
const k = Number(t.k) || 10;
const maxResults = Number(t.max_results) || 15;
const sql = "select * from public.search_all('[" + emb.join(',') + "]'::vector, '" + esc(t.query) + "', " + k + ", " + maxResults + ", " + sourcesArr + ", " + within + ", " + approved + ", " + projectId + ", " + dateFrom + ", " + dateTo + ")";
return { sql };

const rows = $input.all().map(i => i.json).filter(r => r && r.source);
const sources = [...new Set(rows.map(r => r.source))];

let emptyHint;
if (rows.length === 0) {
  const t = $('Sub').first().json;
  const widen = [];
  // approved is tri-state: omitted/null = ALL sessions, true = only approved,
  // false = only UNapproved. Never suggest approved:false — it narrows.
  if (t.approved === true || t.approved === 'true') {
    widen.push('drop the approved filter (omit it entirely — approved:false means ONLY unapproved sessions, a narrower set, not a wider one)');
  }
  if (t.within) widen.push("drop the within scope (you searched '" + t.within + "')");
  if (t.date_from || t.date_to) widen.push('drop or widen the date range');
  if (t.sources) widen.push('broaden sources (omit the sources parameter to search all seven)');
  widen.push('rephrase the query with different terms');
  emptyHint = 'No results. To widen, try in order: ' + widen.join('; ') + '. If none help, the corpus likely has nothing on this — say so rather than retrying with the same terms.';
}

return [{ json: {
  results: rows,
  meta: {
    count: rows.length,
    sources_searched: sources,
    citation_rule: 'Cite deep_link verbatim — never construct or paraphrase URLs.',
    empty_hint: emptyHint
  }
} }];
